draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // two stick figures
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 20);
  ctx.lineTo(W/2 - 50, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 50);
  ctx.lineTo(W/2 - 70, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 50);
  ctx.lineTo(W/2 - 30, H/2 + 70);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 20);
  ctx.lineTo(W/2 + 50, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 50);
  ctx.lineTo(W/2 + 30, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 50);
  ctx.lineTo(W/2 + 70, H/2 + 70);
  ctx.stroke();

  // arms around each other
  ctx.beginPath();
  ctx.moveTo(W/2 - 30, H/2 + 70);
  ctx.lineTo(W/2 + 30, H/2 + 70);
  ctx.stroke();

  // comfortable distance
  ctx.beginPath();
  ctx.moveTo(W/2 - 70, H/2 + 120);
  ctx.lineTo(W/2 + 70, H/2 + 120);
  ctx.lineWidth = 2;
  ctx.strokeStyle = 'gray';
  ctx.stroke();
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // oscillating arms
  ctx.beginPath();
  ctx.moveTo(W/2 - 30, H/2 + 70 + 20 * Math.sin(t));
  ctx.lineTo(W/2 + 30, H/2 + 70 + 20 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
